<?php

declare(strict_types=1);

namespace App\Services;

use Illuminate\Database\Query\Builder;
use Illuminate\Support\Facades\DB;

/**
 * One canonical AuditLog event may address ONE eligible assignee.
 * Historical auxiliary deliveries remain read-compatible but are never
 * generated by new mutations. No broadcasts, unread or dismissal state.
 *
 * The exact event trigger choices remain subject to team/client validation.
 */
final class ActivityNotifications
{
    public const TABLE = 'jairoads_next.audit_notification_recipients';

    public static function verbForAction(string $action): string
    {
        return match ($action) {
            'CREATE' => 'created',
            'UPDATE' => 'updated',
            'DELETE' => 'deleted',
            'ACTIVATE' => 'activated',
            'DEACTIVATE' => 'deactivated',
            'REASSIGN' => 'reassigned',
            'RETIRE' => 'retired',
            default => throw new \InvalidArgumentException('Unsupported business action.'),
        };
    }

    /** Proposed trigger scope in Final-DD Workflows; everything else is audit-only. */
    public static function eligibleEvent(string $actorRole, string $action, string $entity): bool
    {
        if (! in_array($actorRole, ['Admin', 'SuperAdmin'], true)) {
            return false;
        }

        return match ($entity) {
            'MaintenanceRecord' => in_array($action, ['CREATE', 'UPDATE', 'REASSIGN'], true),
            'MonthlyUpdate', 'MaintenanceDocument', 'Media' => in_array($action, ['CREATE', 'UPDATE', 'DELETE'], true),
            default => false,
        };
    }

    /**
     * Resolve the eligible current ManagingEngineer, never a broadcast audience.
     * This runs within the same transaction as the canonical AuditLog INSERT.
     *
     * @param array{account_id:int,role:string,engineer_id:?int} $actor
     * @param array<string,mixed> $new
     * @param array<string,mixed> $old
     * @return array{recipient_user_id:int,notification_message:string}|null
     */
    public function forEvent(array $actor, string $action, string $entity, ?int $id, array $new = [], array $old = []): ?array
    {
        if ($id === null || $id < 1 || ! self::eligibleEvent($actor['role'], $action, $entity)) {
            return null;
        }

        $recordId = match ($entity) {
            'MaintenanceRecord' => $id,
            'MonthlyUpdate' => $this->relatedId('monthly_updates', 'maintenance_id', $id, $new, $old),
            'MaintenanceDocument' => $this->relatedId('maintenance_documents', 'maintenance_id', $id, $new, $old),
            'Media' => ($monthlyId = $this->relatedId('media', 'monthly_update_id', $id, $new, $old)) === null
                ? null : $this->relatedId('monthly_updates', 'maintenance_id', $monthlyId, [], []),
            default => null,
        };
        if ($recordId === null) {
            return null;
        }

        $row = DB::table('jairoads_next.maintenance_records as record')
            ->join('jairoads_next.maintenance_projects as project', 'project.id', '=', 'record.project_id')
            ->join('jairoads_next.road_coverages as road', 'road.id', '=', 'project.road_coverage_id')
            ->where('record.id', $recordId)
            ->first(['record.managing_engineer_id', 'road.lgu_id']);
        if ($row === null) {
            return null;
        }

        $recipient = app(AccountIdentityResolver::class)->eligibleAssignedEngineer(
            (int) $row->managing_engineer_id, (int) $row->lgu_id, $actor['account_id']
        );
        if ($recipient === null) {
            return null;
        }

        return [
            'recipient_user_id' => $recipient,
            'notification_message' => $actor['role'].' '.self::verbForAction($action).' '.$entity.' #'.$id.'.',
        ];
    }

    /** @param array<string,mixed> $new
     * @param array<string,mixed> $old
     */
    private function relatedId(string $table, string $field, int $id, array $new, array $old): ?int
    {
        $value = $new[$field] ?? $old[$field]
            ?? DB::table('jairoads_next.'.$table)->where('id', $id)->value($field);

        return is_numeric($value) && (int) $value > 0 ? (int) $value : null;
    }

    public function available(): bool
    {
        return PostgresBoolean::isTrue(DB::selectOne('SELECT to_regclass(?) IS NOT NULL AS available', [self::TABLE])?->available);
    }

    /** IDs remain canonical AuditLog IDs, not delivery sequence IDs.
     * @return list<array{id:int,notification_message:string,created_at:string}>
     */
    public function feed(int $recipient, int $limit = 20): array
    {
        $legacy = DB::table('jairoads_next.audit_logs as old')
            ->where('old.recipient_user_id', $recipient)->whereNotNull('old.notification_message')
            ->whereRaw("btrim(old.notification_message) <> ''")
            ->select(['old.id', 'old.notification_message', 'old.created_at']);
        $query = $legacy;
        if ($this->available()) {
            $legacy->whereNotExists(static fn (Builder $q) => $q->selectRaw('1')->from(self::TABLE.' as delivery')
                ->whereColumn('delivery.audit_log_id', 'old.id')->where('delivery.recipient_user_id', $recipient));
            $current = DB::table(self::TABLE)->where('recipient_user_id', $recipient)
                ->select(['audit_log_id as id', 'notification_message', 'created_at']);
            $query = $current->unionAll($legacy);
        }

        return array_values(DB::query()->fromSub($query, 'notifications')->orderByDesc('created_at')->orderByDesc('id')
            ->limit(min(20, max(1, $limit)))->get()->map(static fn ($r): array => [
                'id' => (int) $r->id, 'notification_message' => (string) $r->notification_message,
                'created_at' => (string) $r->created_at,
            ])->all());
    }
}
